FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR

VAR_OUTPUT
    elementCount : DINT;
    status       : WORD;
END_VAR

VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR

VAR
    headIndex    : DINT := 1;
    tailIndex    : DINT := 1;
    prevEnqueue  : BOOL := FALSE;
    prevDequeue  : BOOL := FALSE;
END_VAR

// Reset takes priority
IF reset THEN
    headIndex := 1;
    tailIndex := 1;
    elementCount := 0;
    status := 16#0000;
    prevEnqueue := FALSE;
    prevDequeue := FALSE;
    RETURN;
END_IF;

// Detect rising edges
VAR
    enqueueRising : BOOL;
    dequeueRising : BOOL;
END_VAR

enqueueRising := enqueue AND NOT prevEnqueue;
dequeueRising := dequeue AND NOT prevDequeue;

// Default status: no error
status := 16#0000;

// Handle enqueue request
IF enqueueRising THEN
    IF elementCount >= capacity THEN
        status := 16#8002;
    ELSE
        buffer[TO_INT(tailIndex)] := item;
        tailIndex := (tailIndex MOD capacity) + 1;
        elementCount := elementCount + 1;
    END_IF;
END_IF;

// Handle dequeue request
IF dequeueRising THEN
    IF elementCount = 0 THEN
        status := 16#8001;
    ELSE
        item := buffer[TO_INT(headIndex)];
        headIndex := (headIndex MOD capacity) + 1;
        elementCount := elementCount - 1;
    END_IF;
END_IF;

// Update edge detection history
prevEnqueue := enqueue;
prevDequeue := dequeue;

END_FUNCTION_BLOCK

